const item = $input.first();
const transactions = typeof item.json.transactions === 'string' 
  ? JSON.parse(item.json.transactions) 
  : item.json.transactions;

// 1. 按區域分組統計
const regionStats = {};
transactions.forEach(t => {
  if (!regionStats[t.region]) {
    regionStats[t.region] = {
      region: t.region,
      total_amount: 0,
      transaction_count: 0,
      products: []
    };
  }
  regionStats[t.region].total_amount += t.amount;
  regionStats[t.region].transaction_count += 1;
  regionStats[t.region].products.push(t.product);
});

// 2. 依金額降冪排序找出冠軍與墊底
const sorted = [...transactions].sort((a, b) => b.amount - a.amount);
const topDeal = sorted[0];
const lowestDeal = sorted[sorted.length - 1];

// 3. 全局指標計算
const totalRevenue = transactions.reduce((sum, t) => sum + t.amount, 0);
const avgOrderValue = Math.round(totalRevenue / transactions.length);

return [{
  json: {
    report_date: new Date().toISOString().split('T')[0],
    summary: {
      total_transactions: transactions.length,
      total_revenue: totalRevenue,
      avg_order_value: avgOrderValue
    },
    regional_breakdown: Object.values(regionStats).map(r => ({
      region: r.region,
      total: r.total_amount,
      count: r.transaction_count,
      avg: Math.round(r.total_amount / r.transaction_count),
      products: r.products.join(', ')
    })),
    highlights: {
      top_deal: topDeal,
      lowest_deal: lowestDeal
    }
  }
}];
